using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = EvaluationHarness.CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsRelevant()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_Response_IsRelevant));

        IChatClient chatClient = run.GetChatConfiguration()!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages);

        EvaluationResult result = run.Result;

        // Verify relevance score meets threshold
        NumericMetricValue relevance = result.Get<NumericMetricValue>(RelevanceEvaluator.RelevanceMetricName);
        Assert.IsTrue(
            relevance.Value >= 3,
            $"Relevance score {relevance.Value} is below threshold of 3.");
    }

    [TestMethod]
    public async Task Chat_Response_IsCoherent()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_Response_IsCoherent));

        IChatClient chatClient = run.GetChatConfiguration()!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in two sentences.")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages);

        EvaluationResult result = run.Result;

        NumericMetricValue coherence = result.Get<NumericMetricValue>(CoherenceEvaluator.CoherenceMetricName);
        Assert.IsTrue(
            coherence.Value >= 3,
            $"Coherence score {coherence.Value} is below threshold of 3.");
    }

    [TestMethod]
    public async Task Chat_Response_IsFluent()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_Response_IsFluent));

        IChatClient chatClient = run.GetChatConfiguration()!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Summarize the benefits of exercise.")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages);

        EvaluationResult result = run.Result;

        NumericMetricValue fluency = result.Get<NumericMetricValue>(FluencyEvaluator.FluencyMetricName);
        Assert.IsTrue(
            fluency.Value >= 3,
            $"Fluency score {fluency.Value} is below threshold of 3.");
    }
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evaluation;

/// <summary>
/// Configures the evaluation harness with evaluators, chat client, and reporting storage.
/// </summary>
internal static class EvaluationHarness
{
    private static readonly string ResultsDirectory =
        Path.Combine(AppContext.BaseDirectory, "evaluation-results");

    public static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        var storage = new DiskBasedReportingStorage(ResultsDirectory);

        return new ReportingConfiguration(
            chatConfiguration: new ChatConfiguration(CreateChatClient()),
            evaluators: evaluators,
            reportingStorage: storage);
    }

    private static Microsoft.Extensions.AI.IChatClient CreateChatClient()
    {
        // Uses the AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_API_KEY environment variables,
        // or falls back to the Aspire-provisioned connection string named "chat".
        // For local development, set these in your environment or user secrets.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT");
        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY");
        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o";

        if (string.IsNullOrEmpty(endpoint) || string.IsNullOrEmpty(apiKey))
        {
            throw new InvalidOperationException(
                "Set AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_API_KEY environment variables " +
                "to run evaluations. Optionally set AZURE_OPENAI_DEPLOYMENT (defaults to gpt-4o).");
        }

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(apiKey))
            .GetChatClient(deployment)
            .AsIChatClient();
    }
}

